function fail(msg) { finish({ ok: false, error: maskSecrets(String(msg).split('\n')[0]).slice(0, 300) }); console.error(msg); process.exit(1); }

// Credentials in a git URL (or a git error) never reach the screen. Same patterns as tools/usage-report/sync.js.
const maskSecrets = (s) => String(s || '')
  .replace(/(\w+:\/\/)[^/@\s]+@/g, '$1***@')
  .replace(/\b(gh[pousr]_[A-Za-z0-9]{10,}|github_pat_[A-Za-z0-9_]{10,})\b/g, '***')
  .replace(/(authorization:\s*(?:bearer|basic)\s+)\S+/gi, '$1***');

// A file that is locked or not writable (EBUSY, EPERM, ...) ends with one plain line, not a stack trace.
// Anything else is reported the same way to a background update's result file (the add-on would otherwise hear nothing).
function fatal(e) {
  if (e && e.syscall && typeof e.code === 'string') fail(`Could not update ${e.dest || e.path || 'a file'} (${e.code}). Close Claude Code and run this again.`);
  console.error(e && e.stack || String(e));
  finish({ ok: false, error: maskSecrets(String((e && e.message) || e).split('\n')[0]).slice(0, 300) });
  process.exit(1);
}
process.on('uncaughtException', fatal);

